ALTER TABLE tl.people ADD COLUMN kind text DEFAULT 'human', ADD COLUMN source_system text, ADD COLUMN source_id text;
CREATE UNIQUE INDEX people_source ON tl.people(source_system,source_id);
ALTER TABLE tl.person_names ADD COLUMN kind text, ADD COLUMN is_primary boolean DEFAULT false, ADD COLUMN note text, ADD COLUMN source text, ADD COLUMN created_at timestamptz DEFAULT now(), ADD COLUMN retired_at timestamptz;
ALTER TABLE tl.identifiers ADD COLUMN updated_at timestamptz DEFAULT now();
ALTER TABLE tl.facts ADD COLUMN note text, ADD COLUMN source text, ADD COLUMN as_of date, ADD COLUMN created_at timestamptz DEFAULT now(), ADD COLUMN retired_at timestamptz;
ALTER TABLE tl.relations ADD COLUMN note text, ADD COLUMN created_at timestamptz DEFAULT now(), ADD COLUMN ended_at timestamptz;
CREATE TABLE tl.not_same(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, person_a bigint NOT NULL REFERENCES tl.people, person_b bigint NOT NULL REFERENCES tl.people, reason text, created_at timestamptz DEFAULT now(), CHECK(person_a < person_b), UNIQUE(person_a,person_b));
CREATE OR REPLACE VIEW api.people AS SELECT * FROM tl.people;
CREATE OR REPLACE VIEW api.person_names AS SELECT * FROM tl.person_names;
CREATE OR REPLACE VIEW api.identifiers AS SELECT * FROM tl.identifiers;
CREATE OR REPLACE VIEW api.facts AS SELECT * FROM tl.facts WHERE retired_at IS NULL;
CREATE VIEW api.facts_history AS SELECT * FROM tl.facts;
CREATE OR REPLACE VIEW api.relations AS SELECT id,from_id,to_id,kind,asserted_by,note,created_at,ended_at FROM tl.relations WHERE ended_at IS NULL UNION ALL SELECT r.id,r.to_id,r.from_id,k.inverse,r.asserted_by,r.note,r.created_at,r.ended_at FROM tl.relations r JOIN tl.relation_kinds k USING(kind) WHERE r.ended_at IS NULL;
CREATE VIEW api.relations_history AS SELECT * FROM tl.relations;
CREATE VIEW api.not_same AS SELECT * FROM tl.not_same;
CREATE OR REPLACE FUNCTION api.person(query text) RETURNS SETOF api.people LANGUAGE sql STABLE AS $$ SELECT DISTINCT p.* FROM api.people p LEFT JOIN api.person_names n ON n.person_id=p.id AND n.retired_at IS NULL LEFT JOIN api.identifiers i ON i.person_id=p.id WHERE p.handle=query OR p.display_name=query OR n.name=query OR i.value=query OR i.value_norm=query $$;
GRANT SELECT,INSERT,UPDATE ON tl.not_same TO throughline_app;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA tl TO throughline_app;
GRANT SELECT ON ALL TABLES IN SCHEMA api TO throughline_app,throughline_reader;
ALTER FUNCTION api.catalog() RENAME TO catalog_search;
CREATE FUNCTION api.catalog() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT api.catalog_search() || jsonb_build_object('identity_columns',(SELECT jsonb_object_agg(table_name, columns) FROM (SELECT table_name,jsonb_agg(jsonb_build_object('name',column_name,'type',data_type) ORDER BY ordinal_position) columns FROM information_schema.columns WHERE table_schema='api' AND table_name IN ('people','person_names','identifiers','facts','facts_history','relations','relations_history','not_same') GROUP BY table_name) c),'identity_import',jsonb_build_object('person_names','All names, including retired names; retired names do not resolve','facts','Current facts only','facts_history','All facts including retired facts','relations','Current relations in both directions','relations_history','All original relations including ended relations','not_same','Explicit distinct person pairs; owner override required to merge')) $$;
GRANT EXECUTE ON FUNCTION api.catalog() TO throughline_app,throughline_reader;
